const WebSocket = require\('ws'\);
const ws = new WebSocket\('ws://localhost:18789'\);

ws.on\('open', \(\) => {
  console.log\('WebSocket opened, waiting for challenge...'\);
}\);

ws.on\('message', \(data\) => {
  const msg = JSON.parse\(data.toString\(\)\);
  console.log\('Received:', JSON.stringify\(msg, null, 2\)\);

  if \(msg.type === 'event' && msg.event === 'connect.challenge'\) {
    console.log\('Got challenge, sending connect...'\);
    const connectMsg = {
      type: 'req',
      id: 'c1',
      method: 'connect',
      params: {
        minProtocol: 3,
        maxProtocol: 3,
        client: {
          id: 'openclaw-webui-test',
          displayName: 'WebUI Test',
          version: '1.0.0',
          platform: 'web',
          mode: 'ui'
        },
        role: 'operator',
        scopes: ['operator.read', 'operator.write'],
        auth: { token: 'c46ff6f2b336c4894a2cc89270c572083160a1373db5648f' },
        device: {
          id: 'test-device-' + Date.now\(\),
          nonce: msg.payload.nonce
        }
      }
    };
    console.log\('Sending:', JSON.stringify\(connectMsg, null, 2\)\);
    ws.send\(JSON.stringify\(connectMsg\)\);
  }

  if \(msg.type === 'res'\) {
    if \(msg.ok\) {
      console.log\('Connect SUCCESS:', JSON.stringify\(msg.payload, null, 2\)\);
    } else {
      console.log\('Connect FAILED:', JSON.stringify\(msg.error, null, 2\)\);
    }
    ws.close\(\);
  }
}\);

ws.on\('error', \(err\) => {
  console.error\('WebSocket error:', err.message\);
}\);

ws.on\('close', \(code, reason\) => {
  console.log\('WebSocket closed:', code, reason.toString\(\)\);
  process.exit\(0\);
}\);

setTimeout\(\(\) => {
  console.log\('Timeout, closing...'\);
  ws.close\(\);
  process.exit\(1\);
}, 10000\);
